solutionCode:
#[derive(Debug)]
pub struct Ficha {
    pub nome: String,
    pub pontos: i32,
}

impl Ficha {
    pub fn soma(&mut self, ganhou: i32) {
        self.pontos = self.pontos + ganhou;
    }

    pub fn anota(mut self, ganhou: i32) -> Ficha {
        self.soma(ganhou);
        self
    }

    pub fn linha(&self) -> String {
        format!("{} tem {} pontos", self.nome, self.pontos)
    }
}

pub fn turno(nome: String, base: i32, ganhou: i32) -> String {
    Ficha { nome, pontos: base }.anota(ganhou).linha()
}

testsCode:
use desafio::Ficha;
use desafio::turno;

#[test]
fn testa_o_turno_da_ana() {
    assert_eq!(turno(String::from("ana"), 10, 5), "ana tem 15 pontos");
}

#[test]
fn testa_a_ficha_do_bo_depois_do_ganho() {
    let mut ficha = Ficha { nome: String::from("bo"), pontos: 12 };
    desafio::Ficha::soma(&mut ficha, 8);
    assert_eq!(desafio::Ficha::linha(&ficha), "bo tem 20 pontos");
}

#[test]
fn testa_a_ficha_da_ana_anotada() {
    let ficha = desafio::Ficha::anota(Ficha { nome: String::from("ana"), pontos: 10 }, 5);
    assert_eq!(desafio::Ficha::linha(&ficha), "ana tem 15 pontos");
}
